effect.shader:
void main() {
vec2 uv = acScreenNorm;
vec2 center = vec2(centerX, centerY);
vec2 p = uv - center;
float aspect = acScreenSize.x / acScreenSize.y;
p.x *= aspect;
float dist = length(p);
vec2 warpedUV = uv;
if (dist > size) {
float pull = size / dist;
float offsetAmount = pow(pull, 2.0) * distortion;
vec2 shift = normalize(p) * offsetAmount;
shift.x /= aspect;
vec2 dir = normalize(p);
vec2 shiftVector = dir * offsetAmount;
shiftVector.x /= aspect;
warpedUV -= shiftVector;
}
vec4 tex = texture2DCv(inputImg.texture, warpedUV);
float mask = smoothstep(size - feather, size + feather, dist);
if (invert) mask = 1.0 - mask;
gl_FragColor = tex * mask;
}
